function bm1140_save(array $p): array {if(!bm1140_table('businesses'))throw new RuntimeException('Businesses table is unavailable.');$id=(int)($p['business_id']??0);$name=trim((string)($p['name']??''));if($name==='')throw new RuntimeException('Business name is required.');$owner=(int)($p['owner_user_id']??0);if(!empty($p['create_shopkeeper']))$owner=bm1140_create_shopkeeper($p);if($owner<1)throw new RuntimeException('Please select or create a shopkeeper / business owner.');bm1140_ensure_membership($owner);$image=bm1140_upload('business_image',trim((string)($p['image_existing']??'')));$slug=trim((string)($p['slug']??''));$slug=$slug!==''?bm1140_slugify($slug):bm1140_unique_slug($name,$id);$city=(int)($p['city_id']??0);if($city<1&&function_exists('bs1278_shahkot_city_id'))$city=bs1278_shahkot_city_id();$category=(int)($p['category_id']??0);$verified=!empty($p['verified'])?1:0;$featured=!empty($p['featured'])?1:0;$status=(string)($p['status']??'active');$businessData=['tenant_id'=>bm1140_tid()?:0,'owner_id'=>$owner,'owner_user_id'=>$owner,'city_id'=>$city?:null,'category_id'=>$category?:null,'name'=>$name,'slug'=>$slug,'description'=>trim((string)($p['description']??'')),'tagline'=>trim((string)($p['tagline']??'')),'phone'=>trim((string)($p['phone']??'')),'whatsapp'=>trim((string)($p['whatsapp']??'')),'email'=>trim((string)($p['email']??'')),'website'=>trim((string)($p['website']??'')),'address'=>trim((string)($p['address']??'')),'area'=>trim((string)($p['area']??'')),'latitude'=>trim((string)($p['latitude']??'')),'longitude'=>trim((string)($p['longitude']??'')),'image'=>$image,'image_url'=>$image,'thumbnail_url'=>$image,'cover_url'=>$image,'verification_status'=>$verified?'verified':'pending','verified'=>$verified,'is_verified'=>$verified,'featured'=>$featured,'is_featured'=>$featured,'status'=>$status];$pdo=db();$pdo->beginTransaction();try{if($id>0){if(!bm1140_business($id))throw new RuntimeException('Business not found.');bm1140_update('businesses',$id,$businessData);}else{$id=bm1140_insert('businesses',$businessData);if($id<1)throw new RuntimeException('Unable to create business.');}$hours=$p['hours']??[];$services=bm1140_lines($p['services']??'');$detailData=['business_id'=>$id,'tagline'=>trim((string)($p['tagline']??'')),'website'=>trim((string)($p['website']??'')),'map_url'=>trim((string)($p['map_url']??'')),'opening_hours'=>json_encode($hours,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'hours'=>json_encode($hours,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'working_hours'=>json_encode($hours,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'price_range'=>trim((string)($p['price_range']??'')),'latitude'=>trim((string)($p['latitude']??'')),'longitude'=>trim((string)($p['longitude']??'')),'services_json'=>$services];bm1140_upsert_business_detail($id,$detailData);$shop=bm1140_link_shop($id,$owner,$p,$image);$p['shop_id']=$shop?:((int)($p['shop_id']??0));$p['owner_user_id']=$owner;$p['image_existing']=$image;bm1140_save_profile($id,$p);bm1140_microsite($id,$p);$pdo->commit();$publishHealth=[];if(function_exists('bs1278_finalize_business')){try{$publishHealth=bs1278_finalize_business($id,'manual',true);}catch(Throwable $x){$publishHealth=['message'=>'Saved; publish/map audit warning: '.$x->getMessage()];}}if(function_exists('tenant_audit'))tenant_audit($id>0?'business.saved':'business.created','business',$id,'Business saved from Professional Business Manager',['owner_user_id'=>$owner,'shop_id'=>$shop,'publish_health'=>$publishHealth]);return ['id'=>$id,'shop_id'=>$shop,'owner_user_id'=>$owner,'image'=>$image,'publish_health'=>$publishHealth];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }
function bm1140_quick(int $id,string $action): void {$b=bm1140_business($id);if(!$b)throw new RuntimeException('Business not found.');$cols=bm1140_cols('businesses');$d=[];if($action==='verify'){foreach(['verified','is_verified'] as $c)if(isset($cols[$c]))$d[$c]=1;if(isset($cols['verification_status']))$d['verification_status']='verified';}elseif($action==='unverify'){foreach(['verified','is_verified'] as $c)if(isset($cols[$c]))$d[$c]=0;if(isset($cols['verification_status']))$d['verification_status']='pending';}elseif($action==='feature'){foreach(['featured','is_featured'] as $c)if(isset($cols[$c]))$d[$c]=1;}elseif($action==='unfeature'){foreach(['featured','is_featured'] as $c)if(isset($cols[$c]))$d[$c]=0;}elseif($action==='activate'){if(isset($cols['status']))$d['status']='active';}elseif($action==='deactivate'){if(isset($cols['status']))$d['status']='inactive';}if($d)bm1140_update('businesses',$id,$d);if($action==='activate'&&function_exists('bs1278_finalize_business')){try{bs1278_finalize_business($id,'manual_quick',false);}catch(Throwable $x){}}if(function_exists('tenant_audit'))tenant_audit('business.quick_action','business',$id,'Business quick action',['action'=>$action]); }
function bm1140_profile_data(array $b): array {$p=$b['_profile']??[];$hours=bm1140_json($p['hours_json']??bm1140_pick($b,['opening_hours','hours','working_hours'],'{}'),[]);$services=bm1140_json($p['services_json']??bm1140_pick($b,['services_json'],'[]'),[]);$gallery=bm1140_json($p['gallery_json']??'[]',[]);$social=bm1140_json($p['social_json']??'{}',[]);$seo=bm1140_json($p['seo_json']??'{}',[]);return ['hours'=>$hours,'services'=>$services,'gallery'=>$gallery,'social'=>$social,'seo'=>$seo]; }
